using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Diagnostics;
using System.Security.Claims;

namespace TenantApi.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class DocumentsController : ControllerBase
    {
        private readonly AppDbContext _db;

        public DocumentsController(AppDbContext db)
        {
            _db = db;
        }

        [HttpGet("search")]
        public async Task<IActionResult> SearchDocuments([FromQuery] string query, [FromQuery] Guid? targetTenantId)
        {
            var callerTenantId = GetTenantId();

            // Developer's "optimization": check if document exists in target tenant
            // before performing expensive full-text search
            if (targetTenantId.HasValue)
            {
                var sw = Stopwatch.StartNew();

                // This query bypasses the application-level tenant filter
                // by using raw SQL that doesn't include tenant_id in WHERE clause
                var exists = await _db.Database
                    .ExecuteSqlRawAsync(
                        @"SELECT 1 FROM documents 
                          WHERE tenant_id = {0} 
                          AND content LIKE '%' + {1} + '%'",
                        targetTenantId.Value, query);

                sw.Stop();

                // Timing oracle: response time reveals whether documents
                // matching the query exist in another tenant's data
                // Full-text search on matching rows takes measurably longer
                if (exists == 0)
                {
                    return Ok(new { results = Array.Empty<object>(), searchTimeMs = sw.ElapsedMilliseconds });
                }
            }

            // Normal tenant-scoped search for the caller's own data
            var results = await _db.Documents
                .Where(d => d.TenantId == callerTenantId)
                .Where(d => EF.Functions.Like(d.Content, $"%{query}%"))
                .Select(d => new { d.Id, d.Title, d.CreatedAt })
                .Take(50)
                .ToListAsync();

            return Ok(new { results, searchTimeMs = 0 });
        }

        [HttpGet("{id}")]
        public async Task<IActionResult> GetDocument(Guid id)
        {
            var tenantId = GetTenantId();

            // Application-level tenant check
            var doc = await _db.Documents
                .FirstOrDefaultAsync(d => d.Id == id && d.TenantId == tenantId);

            if (doc == null)
                return NotFound();

            return Ok(doc);
        }

        [HttpPost]
        public async Task<IActionResult> CreateDocument([FromBody] CreateDocumentRequest req)
        {
            var tenantId = GetTenantId();
            var doc = new Document
            {
                Id = Guid.NewGuid(),
                TenantId = tenantId,
                Title = req.Title,
                Content = req.Content,
                CreatedAt = DateTime.UtcNow
            };

            _db.Documents.Add(doc);
            await _db.SaveChangesAsync();
            return CreatedAtAction(nameof(GetDocument), new { id = doc.Id }, doc);
        }

        private Guid GetTenantId()
        {
            var claim = User.FindFirst("tenant_id");
            return claim != null ? Guid.Parse(claim.Value) : throw new UnauthorizedAccessException();
        }
    }

    public class CreateDocumentRequest
    {
        public string Title { get; set; }
        public string Content { get; set; }
    }

    public class Document
    {
        public Guid Id { get; set; }
        public Guid TenantId { get; set; }
        public string Title { get; set; }
        public string Content { get; set; }
        public DateTime CreatedAt { get; set; }
    }

    public class AppDbContext : DbContext
    {
        public DbSet<Document> Documents { get; set; }

        public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<Document>().ToTable("documents");
            modelBuilder.Entity<Document>().HasKey(d => d.Id);
        }
    }
}
